gacF(){return"\u0627\u0644\u0646\u0633\u062e\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u0644\u0644\u0639\u0631\u0636 \u0648\u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0628\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0647\u0645\u064a\u0629 \u0641\u0642\u0637. \u0648\u062c\u0648\u062f \u0634\u0627\u0634\u0629 \u0645\u0648\u0627\u0641\u0642\u0629 \u0644\u0627 \u064a\u0639\u0646\u064a \u0627\u0639\u062a\u0645\u0627\u062f\u0627\u064b \u0642\u0627\u0646\u0648\u0646\u064a\u0627\u064b \u0623\u0648 \u062a\u0635\u0631\u064a\u062d\u0627\u064b \u0628\u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u0645\u0639 \u0623\u0637\u0641\u0627\u0644 \u062d\u0642\u064a\u0642\u064a\u064a\u0646."},
gacJ(){return"\u0645\u0648\u0627\u0641\u0642\u0629 \u0627\u0644\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u063a\u064a\u0631 \u0645\u062a\u0627\u062d\u0629: \u064a\u0644\u0632\u0645 \u062a\u062d\u062f\u064a\u062f \u0627\u0644\u062c\u0647\u0629 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u0629 \u0648\u0648\u0633\u064a\u0644\u0629 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0648\u0645\u062f\u0629 \u0627\u0644\u062d\u0641\u0638 \u0648\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0637\u0644\u0628\u0627\u062a\u060c \u0648\u0627\u0639\u062a\u0645\u0627\u062f \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0648\u0622\u0644\u064a\u0629 \u0627\u0644\u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0627\u0644\u0646\u0642\u0644. \u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0641\u062a\u0631\u0636\u0629 \u0644\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0627\u0644\u062d\u0627\u0644\u064a\u0629."},
